 9: - name:  Configure Admin Node
10:   hosts: ohpc_admin_nodes
11:   become: yes
12: 
13:   roles:
14: #  - { role: watermark-release, tags: [ 'always' ] } 
15:   - { role: ansible-role-fgci-repo, tags: [ 'fgci7', 'repos' ] }
16:   - { role: dns, tags: [ 'dns' ] }
17:   - { role: ansible-role-yum, tags: [ 'yum', 'repos' ] }
18:   - { role: ansible-role-ohpc-repo, tags: [ 'yum', 'repos', 'ohpc' ] }
19:   - { role: network_interface, tags: [ 'network' ],
20:     when: internal_interface in ansible_interfaces and
21:           external_interface in ansible_interfaces }
22:   - { role: ip_forwarder, tags: [ 'network' ],
23:     when: internal_interface is defined and
24:           external_interface is defined and
25:           internal_net is defined and
26:           internal_interface in ansible_interfaces and
27:           external_interface in ansible_interfaces }
28:   - { role: ansible-role-hosts-int, tags: [ 'hosts'] }
29:   - { role: ansible-role-ferm-firewall, tags: [ 'firewall', 'network' ] }
30:   - { role: ansible-role-chrony, tags: [ 'ntp', 'chrony' ] }
31:   - { role: ansible-role-yum-cron-2, tags: [ 'yumcron' ] }
32:   - { role: ansible-role-rsyslog, tags: [ 'rsyslog' ] }
33:   - { role: ansible-role-aliases, tags: [ 'aliases', 'email' ] }
34:   - { role: ansible-role-adauth, tags: [ 'auth' ] }
35:   - { role: ansible-role-sshd, tags: [ 'sshd', 'ssh' ] }
36:   - { role: ansible-role-smartd, tags: [ 'smartd' ] }
37:   - { role: ansible-role-dell, tags: [ 'dell' ] }
38:   - { role: ansible-role-rdma, tags: [ 'rdma', 'infiniband' ] }
39:   - { role: ansible-role-postfix, tags: [ 'postfix', 'mail' ] }
40:   - { role: ansible-role-autofs, tags: [ 'autofs' ] }
41:   - { role: ansible-role-pdsh-genders, tags: [ 'pdsh', 'genders' ] }
42:   - { role: ansible-role-systemd-journal, tags: [ 'systemd', 'journal', 'journald' ] }
43:   - { role: ansible-role-slurm, tags: [ 'slurm' ] }
44:   - { role: ansible-role-ohpc-setup, tags: [ 'ohpc' ] }
45:   - { role: ansible-role-lustre_client, tags: [ 'lustre' ], when: lustre_client_enabled }
46: 
