48: #
49: #- import_playbook: admin_local_play.yml
50:

  1: ---
  2: - name: Common tasks for every playbooks
  3:   import_playbook: boilerplate.yml
  4: 
  5: - name: Gather facts
  6:   import_playbook: internal_facts.yml
  7: 
  8: - name: Download images to ansible host cache via first kube_control_plane node
  9:   hosts: kube_control_plane[0]
 10:   gather_facts: false
 11:   any_errors_fatal: "{{ any_errors_fatal | default(true) }}"
 12:   environment: "{{ proxy_disable_env }}"
 13:   roles:
 14:     - { role: kubespray_defaults, when: "not skip_downloads and download_run_once and not download_localhost"}
 15:     - { role: kubernetes/preinstall, tags: preinstall, when: "not skip_downloads and download_run_once and not download_localhost" }
 16:     - { role: download, tags: download, when: "not skip_downloads and download_run_once and not download_localhost" }
 17: 
 18: - name: Prepare nodes for upgrade
 19:   hosts: k8s_cluster:etcd:calico_rr
 20:   gather_facts: false
 21:   any_errors_fatal: "{{ any_errors_fatal | default(true) }}"
 22:   environment: "{{ proxy_disable_env }}"
 23:   roles:
 24:     - { role: kubespray_defaults }
 25:     - { role: kubernetes/preinstall, tags: preinstall }
 26:     - { role: download, tags: download, when: "not skip_downloads" }
 27: 
 28: - name: Upgrade container engine on non-cluster nodes
 29:   hosts: etcd:calico_rr:!k8s_cluster
 30:   gather_facts: false
 31:   any_errors_fatal: "{{ any_errors_fatal | default(true) }}"
 32:   environment: "{{ proxy_disable_env }}"
 33:   serial: "{{ serial | default('20%') }}"
 34:   roles:
 35:     - { role: kubespray_defaults }
 36:     - { role: container-engine, tags: "container-engine", when: deploy_container_engine }
 37: 
 38: - name: Install etcd
 39:   vars:
 40:     etcd_cluster_setup: true
 41:     etcd_events_cluster_setup: "{{ etcd_events_cluster_enabled }}"
 42:   import_playbook: install_etcd.yml
 43: 
 44: - name: Handle upgrades to control plane components first to maintain backwards compat.
 45:   gather_facts: false
 46:   hosts: kube_control_plane
 47:   any_errors_fatal: "{{ any_errors_fatal | default(true) }}"
 48:   environment: "{{ proxy_disable_env }}"
 49:   serial: 1
 50:   roles:
 51:     - { role: kubespray_defaults }
 52:     - { role: upgrade/pre-upgrade, tags: pre-upgrade }
 53:     - { role: upgrade/system-upgrade, tags: system-upgrade }
 54:     - { role: download, tags: download, when: "system_upgrade and system_upgrade_reboot != 'never' and not skip_downloads" }
 55:     - { role: kubernetes-apps/kubelet-csr-approver, tags: kubelet-csr-approver }
 56:     - { role: container-engine, tags: "container-engine", when: deploy_container_engine }
 57:     - { role: kubernetes/node, tags: node }
 58:     - { role: kubernetes/control-plane, tags: control-plane, upgrade_cluster_setup: true }
 59:     - { role: kubernetes/client, tags: client }
 60:     - { role: kubernetes/node-label, tags: node-label }
 61:     - { role: kubernetes/node-taint, tags: node-taint }
 62:     - { role: kubernetes-apps/cluster_roles, tags: cluster-roles }
 63:     - { role: kubernetes-apps, tags: csi-driver }
 64:     - { role: upgrade/post-upgrade, tags: post-upgrade }
 65: 
 66: - name: Upgrade calico and external cloud provider on all control plane nodes, calico-rrs, and nodes
 67:   hosts: kube_control_plane:calico_rr:kube_node
 68:   gather_facts: false
 69:   any_errors_fatal: "{{ any_errors_fatal | default(true) }}"
 70:   serial: "{{ serial | default('20%') }}"
 71:   environment: "{{ proxy_disable_env }}"
 72:   roles:
 73:     - { role: kubespray_defaults }
 74:     - { role: kubernetes-apps/external_cloud_controller, tags: external-cloud-controller }
 75:     - { role: network_plugin, tags: network }
 76:     - { role: kubernetes-apps/policy_controller, tags: policy-controller }
 77: 
 78: - name: Finally handle worker upgrades, based on given batch size
 79:   hosts: kube_node:calico_rr:!kube_control_plane
 80:   gather_facts: false
 81:   any_errors_fatal: "{{ any_errors_fatal | default(true) }}"
 82:   environment: "{{ proxy_disable_env }}"
 83:   serial: "{{ serial | default('20%') }}"
 84:   roles:
 85:     - { role: kubespray_defaults }
 86:     - { role: upgrade/pre-upgrade, tags: pre-upgrade }
 87:     - { role: upgrade/system-upgrade, tags: system-upgrade }
 88:     - { role: download, tags: download, when: "system_upgrade and system_upgrade_reboot != 'never' and not skip_downloads" }
 89:     - { role: container-engine, tags: "container-engine", when: deploy_container_engine }
 90:     - { role: kubernetes/node, tags: node }
 91:     - { role: kubernetes/kubeadm, tags: kubeadm }
 92:     - { role: kubernetes/node-label, tags: node-label }
 93:     - { role: kubernetes/node-taint, tags: node-taint }
 94:     - { role: upgrade/post-upgrade, tags: post-upgrade }
 95: 
 96: - name: Patch Kubernetes for Windows
 97:   hosts: kube_control_plane[0]
 98:   gather_facts: false
 99:   any_errors_fatal: true
100:   environment: "{{ proxy_disable_env }}"
101:   roles:
102:     - { role: kubespray_defaults }
103:     - { role: win_nodes/kubernetes_patch, tags: ["control-plane", "win_nodes"] }
104: 
105: - name: Install Calico Route Reflector
106:   hosts: calico_rr
107:   gather_facts: false
108:   any_errors_fatal: "{{ any_errors_fatal | default(true) }}"
109:   environment: "{{ proxy_disable_env }}"
110:   roles:
111:     - { role: kubespray_defaults }
112:     - { role: network_plugin/calico/rr, tags: network }
113: 
114: - name: Install Kubernetes apps
115:   hosts: kube_control_plane
116:   gather_facts: false
117:   any_errors_fatal: "{{ any_errors_fatal | default(true) }}"
118:   environment: "{{ proxy_disable_env }}"
119:   roles:
120:     - { role: kubespray_defaults }
121:     - { role: kubernetes-apps/ingress_controller, tags: ingress-controller }
122:     - { role: kubernetes-apps/external_provisioner, tags: external-provisioner }
123:     - { role: kubernetes-apps, tags: apps }
124: 
125: - name: Apply resolv.conf changes now that cluster DNS is up
126:   hosts: k8s_cluster
127:   gather_facts: false
128:   any_errors_fatal: "{{ any_errors_fatal | default(true) }}"
129:   environment: "{{ proxy_disable_env }}"
130:   roles:
131:     - { role: kubespray_defaults }
132:     - { role: kubernetes/preinstall, when: "dns_mode != 'none' and resolvconf_mode == 'host_resolvconf'", tags: resolvconf, dns_late: true }

